import Foundation
import StudioVTCoreC
enum GeometrySmoke { static let check: Void = { let g1=TerminalGeometry(backingScale:1); let g2=TerminalGeometry(backingScale:2); precondition(g1.cellPixelSize.width.rounded()==g1.cellPixelSize.width && g2.cellPixelSize.height.rounded()==g2.cellPixelSize.height); precondition(g1.contentInset.left==16 && g1.contentInset.top==12); let gp=g1.origin(for:3,row:2); precondition(g1.cell(at:gp).column==3 && g1.cell(at:gp).row==2) }() }
@main struct Smoke { static func main() { let core=TerminalVTCore(columns:20,rows:4); precondition(core.setTheme(.dark)); precondition(core.snapshot()!.background==VTColor(rgb:0x252A2E)); core.feed(Data("\u{1b}[38;2;1;2;3mA".utf8)); let before=core.snapshot()!; precondition(core.setTheme(.light)); let frame=core.snapshot()!; precondition(frame.background==VTColor(rgb:0xF7F8FA)); precondition(frame.cells[0].text==before.cells[0].text && frame.cells[0].foreground==before.cells[0].foreground); precondition(TerminalTheme.dark.palette.count==256 && TerminalTheme.dark.palette[16]==VTColor(0,0,0) && TerminalTheme.dark.palette[231]==VTColor(255,255,255) && TerminalTheme.dark.palette[232]==VTColor(8,8,8) && TerminalTheme.dark.palette[255]==VTColor(238,238,238)); core.feed(Data("\u{1b}[6n".utf8)); let reply=core.takeQueryResponses(); precondition(reply.first==0x1b && reply.last==0x52); let key=core.encodeKey(key:GHOSTTY_KEY_C,modifiers:GhosttyMods(GHOSTTY_MODS_CTRL),action:GHOSTTY_KEY_ACTION_PRESS,text:""); precondition(key==Data([3])); laneBCounters(); print("TerminalVTCore Swift real smoke passed") }
  static func laneBCounters() { let core=TerminalVTCore(columns:20,rows:4); let s0=core.snapshotCountForTesting(); _=core.snapshot(); _=core.snapshot(); precondition(core.snapshotCountForTesting()==s0+2, "B1: snapshot counter must count every core snapshot"); let p0=core.pwdReadCountForTesting(); core.feed(Data("\u{1b}]7;file://host/tmp/x\u{07}".utf8)); precondition(core.pwdReadCountForTesting()==p0, "B2: feeding must not read the pwd"); precondition(core.pwd()=="file://host/tmp/x" && core.pwdReadCountForTesting()==p0+1, "B2: pwd must return the raw OSC 7 string and count one read"); let r0=core.resizeCountForTesting(); core.resize(columns:30,rows:5); core.resize(columns:30,rows:5); precondition(core.resizeCountForTesting()==r0+2 && core.snapshot()!.columns==30, "B4: resize counter must count every core.resize") } }
